'use strict';
let sourceProject=null,activeAtom=null,reviewChanges={},selectedSegments=new Set(),candidate=null,favoriteRefs={};
const issueTypes={'reading':'阅读不足／切换太快','occlusion':'文字或对象遮挡','proportion':'人物比例不协调','style':'风格不符合预期','audio':'声音过密','other':'其他问题'};
const baseline=o=>o.configuration;
const atom=()=>sourceProject?.objects.find(o=>o.id===activeAtom);
const atoms=()=>sourceProject?sourceProject.objects.filter(o=>current().objectIds.includes(o.id)):[];
const originalExport=window.reviewBase.exportData,originalRenderDesign=window.reviewBase.renderDesign,originalRenderList=window.reviewBase.renderList,originalRenderComments=window.reviewBase.renderComments;
const reviewKey=()=> 'review-v3-'+sourceProject.project.id+'-'+sourceProject.project.revision+'-'+sourceProject.project.videoSha256;
function persist(){if(!sourceProject)return;try{localStorage.setItem(reviewKey(),JSON.stringify({selected:state.selected,openModule:state.openModule,comments:state.comments,changes:reviewChanges,favoriteRefs,activeAtom,selectedSegments:[...selectedSegments]}));$('saveState').textContent='工程审阅已保存'}catch{toast('本地空间不足，请先导出建议')}}
function activeConfig(o){return {...o.configuration,...reviewChanges[state.selected+'|'+o.id]}}
function allChanges(){if(!sourceProject)return [];const list=[];for(const[key,fields]of Object.entries(reviewChanges)){const [segId,objectId]=key.split('|'),s=SEGMENTS.find(s=>s.id===segId),o=sourceProject.objects.find(o=>o.id===objectId);if(!s||!o)continue;for(const[k,v]of Object.entries(fields))if(JSON.stringify(v)!==JSON.stringify(o.configuration[k]))list.push({segment:s,object:o,module:o.module,key:k,from:o.configuration[k]??null,to:v});}return list}
function findFavorite(module){const o=atom();return o&&o.module===module?favorites.find(f=>f.module===module&&sameConfig(f.configuration,activeConfig(o))&&(!f.capabilityId||f.capabilityId===o.capabilityId)):null}
function renderList(){originalRenderList();if(!sourceProject)return;document.querySelectorAll('#segmentList .segment').forEach(b=>{const id=b.dataset.segment;const tick=document.createElement('input');tick.type='checkbox';tick.checked=selectedSegments.has(id);tick.className='batch-tick';tick.setAttribute('aria-label','批量选择 '+id);tick.onclick=e=>{e.stopPropagation();tick.checked?selectedSegments.add(id):selectedSegments.delete(id);persist();updateBatch()};b.prepend(tick)});updateBatch()}
function updateBatch(){const el=$('batchCount');if(el)el.textContent=selectedSegments.size+' 段已选'}
function renderDesign(){originalRenderDesign();if(!sourceProject)return;$('designGrid').innerHTML=MODULES.map(([m,n])=>{const list=atoms().filter(o=>o.module===m);return `<div class="atom-module"><div class="atom-group">${n} <span>${m}</span></div>${list.length?list.map(o=>`<div class="design-row ${o.id===activeAtom?'selected':''}"><button class="row-main" data-atom="${esc(o.id)}"><div><b>${esc(o.title)}</b><span class="module-letter">${esc(o.id)}</span></div><p>${esc(o.design||JSON.stringify(o.configuration))}</p><small>${o.execution==='custom-source-rebuild'?'回源重制':'源配置'}</small></button><button class="star" data-star-atom="${esc(o.id)}" aria-label="收藏 ${esc(o.title)}">☆</button></div>`).join(''):'<div class="module-empty">本镜未使用该模块的独立对象</div>'}</div>`}).join('')}
function renderInspector(){if(!sourceProject)return;let o=atom();if(!o||!current().objectIds.includes(o.id)){o=atoms().find(o=>o.module===state.openModule)||atoms()[0];activeAtom=o?.id}if(!o)return;state.openModule=o.module;const list=atoms().filter(x=>x.module===o.module),config=activeConfig(o);$('inspector').innerHTML=`<div class="module-switch">${MODULES.map(([m,n])=>`<button data-v3-module="${m}" class="${m===o.module?'active':''}">${n}</button>`).join('')}</div><label class="field"><span>具体对象</span><select id="atomSelector">${list.map(x=>`<option value="${esc(x.id)}" ${x.id===o.id?'selected':''}>${esc(x.title)} · ${esc(x.id)}</option>`).join('')}</select></label><p class="scope-note">${esc(o.design)} · ${o.execution==='custom-source-rebuild'?'媒体内部对象，需要重制':'原值读取自工程'}</p>${Object.entries(config).map(([k,v])=>`<label class="field"><span>${esc(k)} <i class="original">原：${esc(JSON.stringify(o.configuration[k]))}</i></span><input data-atom-field="${esc(k)}" value="${esc(typeof v==='object'?JSON.stringify(v):v)}" data-kind="${typeof v}" aria-label="对象配置 ${esc(k)}"></label>`).join('')}<label class="field"><span>建议作用范围</span><select id="batchScope"><option value="one">仅当前对象／片段</option><option value="selected">选中片段内的同一对象</option><option value="kind">选中片段内的同类对象</option></select></label><div class="module-actions"><button id="atomComment">＋ 对象反馈</button><button id="atomFavorite">☆ 收藏此原子</button></div><div class="source">${o.sourceRefs.map(r=>esc(r.file+' :: '+r.stableId+' '+r.field)).join('<br>')}</div>`;$('atomSelector').onchange=e=>{activeAtom=e.target.value;renderInspector();renderDesign();persist()};$('atomComment').onclick=()=>beginComment();$('atomFavorite').onclick=()=>saveAtomFavorite();const related=favorites.filter(f=>f.module===o.module&&f.capabilityId===o.capabilityId).slice(0,3);if(related.length)$('inspector').insertAdjacentHTML('beforeend','<div class="scope-note">同类收藏</div>'+related.map(f=>`<button data-use-favorite="${f.id}" class="module-comment">★ ${esc(f.title)}</button>`).join(''));}
function renderChanges(){if(!sourceProject)return;const list=allChanges().filter(c=>c.segment.id===state.selected);$('miniDemo').className='mini-demo';$('miniDemo').innerHTML='<span>实际源参数建议 · 修改原片需回源制作</span>';$('changeList').innerHTML=list.length?list.map(c=>`<div class="change-item"><button data-v3-revert="${esc(c.object.id)}" data-key="${esc(c.key)}" class="revert">撤销</button><b>${esc(c.object.title)} / ${esc(c.key)}</b><code>${esc(JSON.stringify(c.from))} → ${esc(JSON.stringify(c.to))}</code></div>`).join(''):'<div class="empty">暂无配置建议。选择对象后修改实际源参数。</div>'}
function beginComment(){const t=$('video').currentTime;$('video').pause();contextTime=Math.min(current().end-1/sourceProject.project.fps,Math.max(current().start,t));$('commentModule').value=atom()?.module||'overall';$('commentForm').dataset.frozen='true';renderComments();$('commentText').focus()}
function renderComments(){originalRenderComments();if(!sourceProject)return;const list=state.comments.filter(c=>c.segmentId===state.selected);$('commentList').innerHTML=list.filter(c=>!$('openOnly')?.checked||c.status!=='resolved').map(c=>`<article class="comment-item ${c.status==='resolved'?'resolved':''}"><div class="comment-meta"><span class="badge">${esc(({todo:'待修改',verify:'待复核',resolved:'已解决'})[c.status||'todo'])}</span><b>${esc(c.objectTitle||moduleName(c.module))}</b><button class="jump" data-v3-jump="${c.id}">${format(c.timeSeconds)} ↗</button></div><p>${esc(c.text)}</p><div class="comment-actions"><button data-review="${c.id}">前后对照</button><button data-status="${c.id}" data-value="todo">待修改</button><button data-status="${c.id}" data-value="verify">待复核</button><button data-status="${c.id}" data-value="resolved">确认解决</button></div></article>`).join('')||'<div class="empty">当前筛选下没有问题</div>';renderPins();}
async function loadSource(){try{const r=await fetch('/api/project',{cache:'no-store'}),data=await r.json();if(!r.ok)throw Error(data.error);sourceProject=data;$('video').src='/assets/sample.mp4?v='+data.project.videoSha256;SEGMENTS.splice(0,SEGMENTS.length,...data.segments);const saved=JSON.parse(localStorage.getItem(reviewKey())||'null');state.selected=data.segments[0].id;state.comments=[];state.changes={};if(saved){if(SEGMENTS.some(s=>s.id===saved.selected))state.selected=saved.selected;state.comments=saved.comments||[];reviewChanges=saved.changes||{};favoriteRefs=saved.favoriteRefs||{};activeAtom=saved.activeAtom;selectedSegments=new Set(saved.selectedSegments||[])}activeAtom||=atoms().find(o=>o.module==='text')?.id;document.querySelector('.project').firstChild.textContent=data.project.title;document.querySelector('header>.badge').textContent='真实工程已连接';$('scrubber').max=data.project.durationSeconds;document.querySelector('.transport .timecode:last-of-type').textContent=format(data.project.durationSeconds);document.querySelector('.project small').textContent='真实导演工程 / '+data.project.durationSeconds+' 秒 · '+data.project.fps+' FPS';render();seek(current().preview);$('sourceInfo').textContent='源版本 '+data.project.revision.slice(0,10)+' · '+data.objects.length+' 个可定位对象';document.dispatchEvent(new Event('review-source-ready'));}catch(e){$('sourceInfo').textContent='工程读取失败：'+e.message;toast('无法读取真实工程，未使用示例数据替代')}}
function exportData(){if(!sourceProject)return originalExport();return {schemaVersion:2,type:'video-review-suggestions',project:sourceProject.project,createdAt:new Date().toISOString(),configSuggestions:allChanges().map(c=>({id:c.segment.id+'.'+c.object.id+'.'+c.key,target:{segmentId:c.segment.id,shotId:c.object.shotId,objectId:c.object.id,module:c.module,capabilityId:c.object.capabilityId},sourceRefs:c.object.sourceRefs,favoriteId:favoriteRefs[c.segment.id+'|'+c.object.id]||null,requestedField:c.key,originalValue:c.from,suggestedValue:c.to,scope:'explicit-target',execution:c.object.execution})),comments:state.comments,comparison:candidate?{sha256:candidate.sha256,name:candidate.name,duration:candidate.duration,sourceMapping:'manual-verification-required'}:null,summary:{configSuggestions:allChanges().length,openComments:state.comments.filter(c=>c.status!=='resolved').length,resolvedComments:state.comments.filter(c=>c.status==='resolved').length},instruction:'逐项核对原片与源文件哈希。对象建议不能当作已应用的补丁；媒体内对象回源重制。仅用户复核后标为解决。'}}
window.prototypeExport=exportData;
const tools=document.createElement('div');tools.className='review-tools';tools.innerHTML='<span id="sourceInfo">正在读取真实工程…</span><span id="batchCount">0 段已选</span><button id="selectAllSegments">全选片段</button><label class="upload-btn">导入新版 MP4<input id="newVersion" type="file" accept="video/mp4" hidden></label><button id="openComparison">版本对照</button>';$('designView').before(tools);
const quick=document.createElement('div');quick.className='quick-issues';quick.innerHTML=Object.entries(issueTypes).map(([k,v])=>`<button type="button" data-issue="${k}">${v}</button>`).join('');$('commentText').before(quick);const filter=document.createElement('label');filter.className='scope-note';filter.innerHTML='<input id="openOnly" type="checkbox"> 仅看未解决问题';$('commentList').before(filter);$('openOnly').onchange=renderComments;
const dialog=document.createElement('dialog');dialog.id='compareDialog';dialog.innerHTML='<div class="dialog-head"><h2>按问题复核新版本</h2><button id="closeCompare">关闭</button></div><p id="compareNote">导入新版后按原问题对照。源工程映射尚未确认，时间改变时请校准。</p><div class="comparison-grid"><div>原片<video id="beforeVideo" controls muted src="assets/sample.mp4"></video></div><div>新版<video id="afterVideo" controls muted></video></div></div><label class="field"><span>此问题在新版中的时间（秒）</span><input id="candidateTime" type="number" min="0" step="0.016667"></label><button id="seekCandidate">跳到新版时间</button><label class="scope-note"><input id="confirmMapping" type="checkbox"> 我已核对这条问题在新版中的对应画面与时间</label><button id="resolveCompared" class="primary">确认此问题已解决</button>';document.body.append(dialog);let comparingId=null;
function openComparison(id){comparingId=id||null;const c=state.comments.find(c=>c.id===id);$('beforeVideo').currentTime=c?.timeSeconds||$('video').currentTime;$('candidateTime').value=c?.verification?.timeSeconds??c?.timeSeconds??$('video').currentTime;$('confirmMapping').checked=false;$('resolveCompared').disabled=!id||!candidate;$('compareNote').textContent=c?'问题：'+c.text+'。新版时间需人工核对，不能因导入文件就自动判为已修复。':'选择一条问题进行前后复核。';$('compareDialog').showModal()}
$('openComparison').onclick=()=>openComparison();$('closeCompare').onclick=()=>{$('beforeVideo').pause();$('afterVideo').pause();$('compareDialog').close()};$('seekCandidate').onclick=()=>{if(candidate)$('afterVideo').currentTime=Math.min(candidate.duration,Math.max(0,Number($('candidateTime').value)))};$('resolveCompared').onclick=()=>{if(!candidate||!$('confirmMapping').checked)return toast('请先核对新版对应画面与时间');const c=state.comments.find(c=>c.id===comparingId);const t=Number($('candidateTime').value);if(!Number.isFinite(t)||t<0||t>=candidate.duration)return toast('新版时间超出片长');c.status='resolved';c.resolved=true;c.verification={candidateSha256:candidate.sha256,timeSeconds:t,frame:null,timeBasis:'media-seconds',referenceFrameAtSourceFps:Math.round(t*sourceProject.project.fps),mapping:'user-confirmed',checkedAt:new Date().toISOString()};persist();render();$('compareDialog').close()};
$('newVersion').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>32*1024*1024)return toast('新版预览上限 32 MiB，请导入压缩预览片');if(candidate)URL.revokeObjectURL(candidate.url);candidate=null;let url;try{const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))].map(b=>b.toString(16).padStart(2,'0')).join('');url=URL.createObjectURL(file);const v=$('afterVideo');await new Promise((resolve,reject)=>{v.onloadedmetadata=resolve;v.onerror=()=>reject(Error('无法解码新版视频'));v.src=url});if(!Number.isFinite(v.duration)||v.duration<=0)throw Error('新版片长不正确');candidate={url,sha256:hash,name:file.name,duration:v.duration};toast('新版仅载入内存，请逐项复核');openComparison()}catch(err){if(url)URL.revokeObjectURL(url);$('afterVideo').removeAttribute('src');toast(err.message)}};

$('selectAllSegments').onclick=()=>{selectedSegments=new Set(selectedSegments.size===SEGMENTS.length?[]:SEGMENTS.map(s=>s.id));persist();renderList()};
$('commentText').addEventListener('focus',()=>{if(!$('commentForm').dataset.frozen)beginComment()});$('commentForm').onsubmit=e=>{e.preventDefault();if(!sourceProject)return;const text=$('commentText').value.trim(),o=$('commentForm').dataset.overall==='true'?null:atom();if(!text)return;state.comments.push({id:'issue-'+crypto.randomUUID(),segmentId:state.selected,shotId:current().shotId,objectId:o?.id,module:o?.module||'overall',objectTitle:o?.title,sourceRefs:o?.sourceRefs||[],sourceRevision:sourceProject.project.revision,sourceVideoSha256:sourceProject.project.videoSha256,timeSeconds:contextTime,frame:Math.round(contextTime*sourceProject.project.fps),localSeconds:contextTime-current().start,text,issueType:$('commentForm').dataset.issue||'other',priority:$('commentPriority').value,anchor:pendingAnchor?{space:'video-normalized',...pendingAnchor}:null,status:'todo',resolved:false,createdAt:new Date().toISOString()});pendingAnchor=null;$('commentText').value='';delete $('commentForm').dataset.frozen;persist();render();toast('已绑定对象、当前帧与真实源版本')};
document.addEventListener('change',e=>{if(!e.target.dataset.atomField||!sourceProject)return;const field=e.target.dataset.atomField,o=atom(),scope=$('batchScope').value;let val=e.target.value;if(e.target.dataset.kind==='number'){val=Number(val);if(!Number.isFinite(val))return toast('请输入有效数值')}if(e.target.dataset.kind==='object'){try{val=JSON.parse(val)}catch{return toast('JSON 格式不正确')}}const targets=(scope==='one'?[current()]:SEGMENTS.filter(s=>selectedSegments.has(s.id))).flatMap(s=>sourceProject.objects.filter(x=>s.objectIds.includes(x.id)&&(scope==='kind'?x.capabilityId===o.capabilityId:x.id===o.id)&&field in x.configuration).map(x=>({s,o:x})));if(!targets.length)return toast('先选择需要批量修改的片段');if(scope!=='one'&&!confirm('将为以下对象生成建议（原片不变）：\n'+targets.map(t=>t.s.id+' / '+t.o.title).join('\n')))return;for(const t of targets){const k=t.s.id+'|'+t.o.id;reviewChanges[k]??={};if(JSON.stringify(val)===JSON.stringify(t.o.configuration[field]))delete reviewChanges[k][field];else reviewChanges[k][field]=val}state.tab='changes';persist();render();toast('已生成 '+targets.length+' 个明确目标的建议')});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.atom){activeAtom=b.dataset.atom;renderInspector();renderDesign();persist()}if(b.dataset.v3Module){const o=atoms().find(o=>o.module===b.dataset.v3Module);if(!o)return toast('当前片段未使用该模块的独立对象');activeAtom=o.id;renderInspector();renderDesign();persist()}if(b.dataset.starAtom){activeAtom=b.dataset.starAtom;saveAtomFavorite()}if(b.dataset.issue){beginComment();$('commentForm').dataset.issue=b.dataset.issue;$('commentText').value=issueTypes[b.dataset.issue]+'；期望：';}if(b.dataset.v3Revert){delete reviewChanges[state.selected+'|'+b.dataset.v3Revert]?.[b.dataset.key];persist();render()}if(b.dataset.v3Jump){const c=state.comments.find(c=>c.id===b.dataset.v3Jump);activeAtom=c.objectId;seek(c.timeSeconds);renderInspector()}if(b.dataset.review)openComparison(b.dataset.review);if(b.dataset.status){const c=state.comments.find(c=>c.id===b.dataset.status);if(b.dataset.value==='resolved')return openComparison(c.id);c.status=b.dataset.value;c.resolved=false;persist();renderComments();updateCounts()}});
$('stage').addEventListener('dblclick',e=>{if(!sourceProject||pinMode)return;const r=$('stage').getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;const o=atoms().filter(o=>o.bounds&&(!Number.isFinite(o.startFrame)||$('video').currentTime*sourceProject.project.fps>=o.startFrame)).reverse().find(o=>x>=o.bounds.x&&x<=o.bounds.x+o.bounds.width&&y>=o.bounds.y&&y<=o.bounds.y+o.bounds.height);if(o){activeAtom=o.id;renderInspector();renderDesign();beginComment();toast('已选中 '+o.title)}else toast('此处无对象边界映射，可用定点评论')});
async function saveAtomFavorite(){const o=atom();if(!o)return;const name=prompt('收藏名称',o.title);if(!name)return;const tagInput=prompt('用途标签（逗号分隔）',moduleName(o.module));if(tagInput===null)return;const tags=tagInput.split(/[,，]/).map(s=>s.trim()).filter(Boolean).slice(0,8);const applicability=prompt('适用条件','新片复用前核对构图与内容');if(applicability===null)return;try{const cfg=activeConfig(o);for(const v of Object.values(cfg))if(v&&typeof v==='object')return toast('复杂配置请先提炼为小型原子参数');acceptFavorites(await favoriteRequest('/add',{module:o.module,title:name,design:o.design||o.title,configuration:cfg,capabilityId:o.capabilityId,tags,applicability,basis:allChanges().some(c=>c.object.id===o.id)?'proposed-config':'current-render',source:{projectId:sourceProject.project.id,segmentId:state.selected,shotId:o.shotId,event:current().event,atomId:o.id,sourceVideoSha256:sourceProject.project.videoSha256,timeSeconds:$('video').currentTime}}));toast('具体原子设计已收藏到仓库')}catch(e){toast(e.message)}}
// Favorite references remain suggestions and preserve the selected atom identity.
document.addEventListener('click',e=>{const b=e.target.closest('[data-use-favorite]');if(!b||!sourceProject)return;e.preventDefault();e.stopImmediatePropagation();const f=favorites.find(f=>f.id===b.dataset.useFavorite),o=atom();if(!f||!o||o.module!==f.module||f.capabilityId&&f.capabilityId!==o.capabilityId)return toast('请选择同类原子后引用收藏');const fields=Object.entries(f.configuration).filter(([k])=>k in o.configuration);favoriteRefs[state.selected+'|'+o.id]=f.id;reviewChanges[state.selected+'|'+o.id]=Object.fromEntries(fields.filter(([k,v])=>JSON.stringify(v)!==JSON.stringify(o.configuration[k])));state.tab='changes';persist();render();$('favoritesDialog').close();toast('收藏已匹配到 '+o.title+'；仅产生建议')},true);
loadSource();

function renderFavoriteList(){window.reviewBase.renderFavoriteList();for(const card of document.querySelectorAll('.favorite-item')){const id=card.querySelector('[data-use-favorite]')?.dataset.useFavorite,f=favorites.find(f=>f.id===id);if(f){const p=document.createElement('p');p.textContent=(f.tags||[]).map(t=>'#'+t).join(' ')+' · '+(f.applicability||'按新片核对适用条件');card.querySelector('.favorite-config').after(p)}}}

$('resetBtn').onclick=()=>{if(!sourceProject)return;if(!confirm('清空当前源版本的审阅建议？仓库收藏不会改变。'))return;reviewChanges={};favoriteRefs={};selectedSegments.clear();state.comments=[];state.tab='design';state.selected=SEGMENTS[0].id;activeAtom=atoms()[0]?.id;pendingAnchor=null;delete $('commentForm').dataset.frozen;persist();render();seek(current().preview)};
$('commentModule').onchange=e=>{if(e.target.value==='overall'){$('commentForm').dataset.overall='true';return}delete $('commentForm').dataset.overall;const o=atoms().find(o=>o.module===e.target.value);if(o){activeAtom=o.id;renderInspector();renderDesign();toast('反馈对象切换到 '+o.title)}else toast('本段没有该模块的独立对象')};
const sourceSelection=document.createElement('div');sourceSelection.id='sourceSelection';sourceSelection.style.cssText='position:absolute;border:2px solid #efbb6b;pointer-events:none;display:none;z-index:1;box-sizing:border-box';$('stage').append(sourceSelection);
function updateObjectSelection(){const o=atom(),r=o?.bounds;const show=r&&sourceProject&&$('video').currentTime*sourceProject.project.fps>=(o.startFrame||0);sourceSelection.style.display=show?'block':'none';if(show){sourceSelection.style.left=r.x*100+'%';sourceSelection.style.top=r.y*100+'%';sourceSelection.style.width=r.width*100+'%';sourceSelection.style.height=r.height*100+'%'}}
