function seek(t){const fps=sourceProject?.project.fps||60,duration=sourceProject?.project.durationSeconds||6;$('video').currentTime=Math.max(0,Math.min(duration-1/fps,t));contextTime=$('video').currentTime;updateTransport();renderComments()}
// Export is a review surface first; JSON is a secondary representation.
let exportView='overview',exportEdit=null,exportUndo=null,exportFilter='all';
const exportToolbar=document.createElement('div');exportToolbar.className='export-toolbar';exportToolbar.innerHTML='<div class="export-tabs"><button data-export-view="overview" class="active">建议总览</button><button data-export-view="json">原始 JSON</button></div><select id="exportFilter" aria-label="筛选建议"><option value="all">全部建议</option><option value="config">配置修改</option><option value="comments">全部评论</option><option value="open">未解决评论</option></select><button id="undoExport" disabled>撤销删除</button>';$('exportJson').before(exportToolbar);const exportOverview=document.createElement('div');exportOverview.id='exportOverview';$('exportJson').before(exportOverview);$('exportDialog').querySelector('h2').textContent='检查建议，再带回聊天。';$('exportDialog').querySelector(':scope > p').textContent='按片段核对配置修改与评论，可直接编辑或删除。修改会同步到工作台草稿；复制与下载始终使用最新保存的内容。';
function syncExportJson(){const data=exportData();$('exportJson').value=JSON.stringify(data,null,2);$('exportSummary').innerHTML=`<span>${data.summary.configSuggestions} 项配置建议</span><span>${data.summary.openComments} 条未解决评论</span><span>${data.summary.resolvedComments} 条已解决</span>`;return data}
function exportConfigId(c){return c.segment.id+'|'+c.object.id+'|'+c.key}
function renderExportOverview(){const data=syncExportJson();$('exportJson').classList.toggle('hidden',exportView!=='json');exportOverview.classList.toggle('hidden',exportView!=='overview');$('exportFilter').classList.toggle('hidden',exportView==='json');document.querySelectorAll('[data-export-view]').forEach(b=>{b.classList.toggle('active',b.dataset.exportView===exportView);b.disabled=!!exportEdit});$('exportFilter').disabled=!!exportEdit;$('copyJson').disabled=!!exportEdit;$('downloadJson').disabled=!!exportEdit;$('undoExport').disabled=!exportUndo||!!exportEdit;const configs=allChanges(),groups=SEGMENTS.map(s=>({s,configs:configs.filter(c=>c.segment.id===s.id),comments:state.comments.filter(c=>c.segmentId===s.id)}));const orphan=state.comments.filter(c=>!SEGMENTS.some(s=>s.id===c.segmentId));if(orphan.length)groups.push({s:{id:'unmatched',number:'?',title:'未匹配片段'},configs:[],comments:orphan});let total=0;exportOverview.innerHTML=groups.map(({s,configs,comments})=>{if(['comments','open'].includes(exportFilter))configs=[];if(exportFilter==='config')comments=[];if(exportFilter==='open')comments=comments.filter(c=>c.status!=='resolved');total+=configs.length+comments.length;if(!configs.length&&!comments.length)return '';return `<section class="export-group"><div class="export-group-head"><b>${esc(s.number)} · ${esc(s.title)}</b><span>${configs.length+comments.length} 项</span></div>${configs.map(c=>{const id=exportConfigId(c),editing=exportEdit?.kind==='config'&&exportEdit.id===id;return `<article class="export-item"><div class="export-item-head"><span class="badge orange">配置</span><b>${esc(c.object.title)}</b><span>${moduleName(c.module)} / ${esc(c.key)}</span></div><div class="export-diff"><span>原值 <code>${esc(JSON.stringify(c.from))}</code></span><span>→</span><span>建议 <code>${esc(JSON.stringify(c.to))}</code></span></div><small class="source">${c.object.sourceRefs.map(r=>esc(r.file+' :: '+r.stableId+' '+r.field)).join('<br>')}</small>${editing?`<div class="export-editor"><label>建议值（${typeof c.to}）<input id="exportConfigValue" value="${esc(typeof c.to==='object'?JSON.stringify(c.to):c.to)}" aria-label="编辑建议值"></label><span class="export-error" id="exportError"></span><div><button data-export-cancel>取消</button><button class="primary" data-export-save>保存修改</button></div></div>`:`<div class="export-item-actions"><button data-export-edit-config="${esc(id)}" ${exportEdit?'disabled':''}>编辑</button><button data-export-delete-config="${esc(id)}" ${exportEdit?'disabled':''}>删除建议</button></div>`}</article>`}).join('')}${comments.map(c=>{const editing=exportEdit?.kind==='comment'&&exportEdit.id===c.id;return `<article class="export-item"><div class="export-item-head"><span class="badge">${({todo:'待修改',verify:'待复核',resolved:'已解决'})[c.status||'todo']}</span><b>${esc(c.objectTitle||moduleName(c.module))}</b><span>${format(c.timeSeconds)} · ${esc(c.priority||'normal')}</span></div>${editing?`<div class="export-editor"><textarea id="exportCommentValue" maxlength="2000" aria-label="编辑评论">${esc(c.text)}</textarea><label>优先级<select id="exportCommentPriority"><option value="normal" ${c.priority==='normal'?'selected':''}>一般建议</option><option value="high" ${c.priority==='high'?'selected':''}>优先修复</option><option value="low" ${c.priority==='low'?'selected':''}>细节优化</option></select></label>${c.status==='resolved'?'<small>修改已解决评论的内容后，将重新进入待复核。</small>':''}<span class="export-error" id="exportError"></span><div><button data-export-cancel>取消</button><button class="primary" data-export-save>保存修改</button></div></div>`:`<p class="export-comment-text">${esc(c.text)}</p><small class="source">${esc(c.objectId||'整体')} · 原片第 ${c.frame} 帧${c.anchor?' · 含画面定位':''}</small><div class="export-item-actions"><button data-export-edit-comment="${c.id}" ${exportEdit?'disabled':''}>编辑</button><button data-export-delete-comment="${c.id}" ${exportEdit?'disabled':''}>删除评论</button></div>`}</article>`}).join('')}</section>`}).join('');if(!total)exportOverview.innerHTML='<div class="empty">'+(data.summary.configSuggestions+data.comments.length?'此筛选下没有建议。':'还没有建议。可在工作台调整配置，或添加定点评论。')+'</div>';}
function commitExportEdit(){if(!exportEdit)return;const changedAt=new Date().toISOString();if(exportEdit.kind==='config'){const c=allChanges().find(c=>exportConfigId(c)===exportEdit.id);if(!c)return;let next=$('exportConfigValue').value;try{if(typeof c.to==='number'){if(!next.trim()||!Number.isFinite(Number(next)))throw Error('请输入有限数值');next=Number(next)}else if(typeof c.to==='boolean'){if(!['true','false'].includes(next))throw Error('布尔值只能是 true 或 false');next=next==='true'}else if(typeof c.to==='object'){next=JSON.parse(next);if((Array.isArray(next)!==Array.isArray(c.to))||next===null)throw Error('请保留原配置的数据类型')}if(typeof next==='string'&&next.length>2000)throw Error('建议值不能超过 2000 字符');const target=c.segment.id+'|'+c.object.id;if(JSON.stringify(next)===JSON.stringify(c.from))delete reviewChanges[target][c.key];else reviewChanges[target][c.key]=next;}catch(e){$('exportError').textContent=e.message;return}}else{const c=state.comments.find(c=>c.id===exportEdit.id),next=$('exportCommentValue').value.trim();if(!next){$('exportError').textContent='评论内容不能为空';return}if(next!==c.text&&c.status==='resolved'){c.status='verify';c.resolved=false;c.previousVerification=c.verification||null;delete c.verification;}c.text=next;c.priority=$('exportCommentPriority').value;c.updatedAt=changedAt;}exportEdit=null;persist();render();renderExportOverview();toast('修改已保存，导出内容已同步')}
function removeExportItem(kind,id){if(exportEdit)return;if(kind==='config'){const c=allChanges().find(c=>exportConfigId(c)===id);if(!c)return;exportUndo={kind,target:c.segment.id+'|'+c.object.id,key:c.key,value:structuredClone(c.to)};delete reviewChanges[exportUndo.target][c.key];}else{const index=state.comments.findIndex(c=>c.id===id);if(index<0)return;exportUndo={kind,index,value:structuredClone(state.comments[index])};state.comments.splice(index,1);}persist();render();renderExportOverview();toast('已删除，可撤销；原片未改动')}
$('exportBtn').onclick=()=>{if(!sourceProject)return toast('真实工程尚未连接');exportEdit=null;exportView='overview';renderExportOverview();$('exportDialog').showModal()};$('exportFilter').onchange=e=>{exportFilter=e.target.value;renderExportOverview()};$('undoExport').onclick=()=>{if(!exportUndo)return;const u=exportUndo;exportUndo=null;if(u.kind==='config'){reviewChanges[u.target]??={};reviewChanges[u.target][u.key]=u.value;}else if(!state.comments.some(c=>c.id===u.value.id))state.comments.splice(Math.min(u.index,state.comments.length),0,u.value);persist();render();renderExportOverview();toast('已恢复删除项')};
$('exportDialog').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.exportView){exportView=b.dataset.exportView;renderExportOverview()}if(b.dataset.exportEditConfig){exportEdit={kind:'config',id:b.dataset.exportEditConfig};renderExportOverview();$('exportConfigValue').focus()}if(b.dataset.exportEditComment){exportEdit={kind:'comment',id:b.dataset.exportEditComment};renderExportOverview();$('exportCommentValue').focus()}if('exportCancel'in b.dataset){exportEdit=null;renderExportOverview()}if('exportSave'in b.dataset)commitExportEdit();if(b.dataset.exportDeleteConfig)removeExportItem('config',b.dataset.exportDeleteConfig);if(b.dataset.exportDeleteComment)removeExportItem('comment',b.dataset.exportDeleteComment)});
$('closeExport').onclick=()=>{if(exportEdit&&!confirm('放弃这条尚未保存的编辑？'))return;exportEdit=null;$('exportDialog').close()};$('exportDialog').addEventListener('cancel',e=>{if(exportEdit&&!confirm('放弃这条尚未保存的编辑？'))e.preventDefault();else exportEdit=null});
const priorCopy=$('copyJson').onclick,priorDownload=$('downloadJson').onclick;$('copyJson').onclick=async()=>{if(exportEdit)return;syncExportJson();await priorCopy()};$('downloadJson').onclick=()=>{if(exportEdit)return;syncExportJson();priorDownload()};
